            C++

    #include <iostream>
#include <vector>
using namespace std;

void segregate0and1(vector<int>& arr) {

    int n = arr.size();

    // Initialize lo and hi indexes
    int lo = -1, hi = n;

    while (true) {

        // Increment lo index while we see 0 at lo
        do {
            lo++;
        } while (lo < n && arr[lo] == 0);

        // Decrement hi index while we see 1 at hi
        do {
            hi--;
        } while (hi >= 0 && arr[hi] == 1);

        // Break when pointers cross
        if (lo >= hi)
            break;

        // Swap elements
        swap(arr[lo], arr[hi]);
    }
}

int main() {
    vector<int> arr = {0, 1, 0, 1, 1, 1};

    segregate0and1(arr);
    for (int x : arr)
        cout << x << " ";
    return 0;
}


